#!/bin/sh
# Build-time setup of the TEST-ONLY sshd users (package 7). Seed files come from
# tests/fixtures/TEST-ONLY/sshd (generated by tests/fixtures/generate.py).
set -eu
seed=/etc/portkey-test

grep -v '^#' "$seed/users.tsv" | while IFS="$(printf '\t')" read -r user shell password; do
    [ -n "$user" ] || continue
    useradd --create-home --shell "$shell" "$user"
    printf '%s:%s\n' "$user" "$password" | chpasswd
done

# keyonly: fixture public keys pre-seeded.
install -d -m 700 -o keyonly -g keyonly /home/keyonly/.ssh
install -m 600 -o keyonly -g keyonly "$seed/keyonly_authorized_keys" \
    /home/keyonly/.ssh/authorized_keys

# tfa: TOTP secret for pam_google_authenticator (owner-only, or the module refuses it).
install -m 600 -o tfa -g tfa "$seed/tfa_google_authenticator" /home/tfa/.google_authenticator

# badperms: a world-writable ~/.ssh, so StrictModes ignores any authorized_keys in it.
install -d -m 777 -o badperms -g badperms /home/badperms/.ssh

# fresh, pw, fishy, nosh: no ~/.ssh at all.
